/**
 * ZoneTable Component
 *
 * Renders editable zone rows with inline editing for names and values.
 */

import { useTranslate } from "../../../../i18n/use-translate";
import type { ZoneRowData, ZoneTableCallbacks } from "../types/zone-table";
import { ZoneRow } from "./ZoneRow";

type ZoneTableProps = {
  zones: Array<ZoneRowData>;
  type: "heartRate" | "power" | "pace";
  threshold?: number;
  isCustom: boolean;
  callbacks: ZoneTableCallbacks;
  onAddZone?: () => void;
};

export function ZoneTable({
  zones,
  type,
  threshold,
  isCustom,
  callbacks,
  onAddZone,
}: ZoneTableProps) {
  const t = useTranslate("zones");
  if (zones.length === 0) {
    return (
      <p className="text-sm text-gray-500 dark:text-gray-400">
        {t("table.noZones")}
      </p>
    );
  }

  return (
    <div className="space-y-1">
      {zones.map((zone, i) => (
        <ZoneRow
          key={zone.zone}
          zone={zone}
          index={i}
          type={type}
          threshold={threshold}
          isCustom={isCustom}
          callbacks={callbacks}
        />
      ))}
      {isCustom && onAddZone && (
        <button
          type="button"
          onClick={onAddZone}
          className="mt-2 rounded border border-dashed border-gray-300 px-3
            py-1 text-xs text-gray-500 hover:border-edge-strong hover:text-ink-strong
            dark:border-gray-600 dark:text-gray-400"
        >
          {t("table.addZone")}
        </button>
      )}
    </div>
  );
}
